import type { IconComponent } from '@wix/wix-ui-icons-common/core';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { PluginContainerData_Alignment } from './../../ricos-schema/next-schema/index.js';
import { DropdownModal } from './../dropdown-modal/dropdown-modal.js';
import { ListItemDivider } from './../list-item-divider/list-item-divider.js';
import { ListItemSelect } from './../list-item-select/list-item-select.js';
import { ListItemToggle } from './../list-item-toggle/list-item-toggle.js';

type NodeAlignmentDropdownProps = {
  onSelect: (commandKey: PluginContainerData_Alignment) => void;
  onToggle?: () => void;
  closeModal: () => void;
  selectedId: PluginContainerData_Alignment;
  options: (
    | {
        type: 'button';
        id: string;
        dataHook: string;
        label: string;
        iconMobile: IconComponent;
        icon: IconComponent;
      }
    | {
        type: 'toggle';
        id: string;
        dataHook: string;
        label: string;
        selected: boolean;
        disabled: boolean;
        infoContent: string | undefined;
      }
  )[];
};

export const NodeAlignmentDropdown: React.FC<NodeAlignmentDropdownProps> = ({
  options,
  onSelect,
  onToggle,
  selectedId,
  closeModal,
}) => {
  const { t, isMobile } = useContext(RicosContext);
  const [isToggleSelected, setIsToggleSelected] = React.useState(
    () => options.find(option => option.type === 'toggle')?.selected ?? false
  );

  const AlignmentDropdownOptions = options
    .filter(option => option.type === 'button')
    .map(({ dataHook, icon: Icon, iconMobile: IconMobile, label, id: commandKey }) => (
      <ListItemSelect
        key={commandKey}
        dataHook={dataHook}
        prefix={isMobile ? <IconMobile /> : <Icon />}
        title={label}
        selected={commandKey === selectedId}
        onSelect={() => {
          onSelect(commandKey as PluginContainerData_Alignment);
          closeModal();
        }}
      />
    ));

  const textWrapToggle = options.find(option => option.type === 'toggle');

  return (
    <DropdownModal
      onCloseButtonClick={closeModal}
      title={t('NodeAlignmentDropdown_Title')}
      options={
        textWrapToggle
          ? [
              ...AlignmentDropdownOptions,
              ...[
                <ListItemDivider key="divider" />,
                <ListItemToggle
                  key={textWrapToggle.id}
                  dataHook={textWrapToggle.dataHook}
                  onChange={() => {
                    onToggle?.();
                    // this is a little workaround to make toggle reactive
                    setIsToggleSelected(prev => !prev);
                  }}
                  title={textWrapToggle.label}
                  selected={isToggleSelected}
                  infoContent={textWrapToggle.infoContent}
                  disabled={textWrapToggle.disabled}
                />,
              ],
            ]
          : AlignmentDropdownOptions
      }
    />
  );
};
