/* oxlint-disable no-unused-vars, camelcase */

import type { VisitorUploads } from './../../ricos-common/ricos-types.js';
import type { RicosServices } from './../../ricos-types/index.js';

import type { MediaPrivacy } from './consts.js';
import { MEDIA_SERVICES_URL } from './consts.js';
import type {
  MediaManagerSDKError,
  RawAudioData,
  RawFileData,
  RawImageData,
  RawVideoData,
} from './upload-types.js';

export const createUploadFn = (services: Pick<RicosServices, 'editorProps' | 'wixInstance'>) => {
  const consumer = services.editorProps.biSettings?.consumer;
  const { uid, siteOwnerId, getWixClientPromise } = services.wixInstance();
  const folderId = getFolderId(uid, siteOwnerId, services.editorProps.visitorUploads);

  return async (
    file: File,
    type: string,
    options?: {
      privacy?: MediaPrivacy;
      onUploadProgress?: (progressEvent: any) => void;
    }
  ): Promise<RawImageData & RawVideoData & RawAudioData & RawFileData> => {
    const { privacy = 'public', onUploadProgress } = options || {};

    const params = new URLSearchParams({ mediaType: type, privacy });
    const wixClient = await getWixClientPromise();
    const response = await wixClient.fetchWithAuth(
      `${MEDIA_SERVICES_URL}/upload-url?${params.toString()}`,
      { method: 'POST', body: JSON.stringify({}) }
    );

    const responseData: { uploadUrl: string } = await response.json();

    const uploadUrl: string = responseData.uploadUrl;
    const formData = new FormData();
    formData.append('file', file, file.name);
    formData.append('media_type', type);
    formData.append('acl', privacy);
    if (consumer) {
      formData.append('tags', `rich_content_${consumer}`);
    }
    if (folderId) {
      formData.append('parent_folder_id', folderId);
    }

    const requestConfig = {
      onUploadProgress: (progressEvent: $TSFixMe) => {
        onUploadProgress?.(progressEvent);
      },
    };

    const uploadResponse = await wixClient.fetchWithAuth(uploadUrl, {
      method: 'POST',
      body: formData,
      ...requestConfig,
    });

    const uploadRepsonseJson: [RawImageData & RawVideoData & RawAudioData & RawFileData] &
      MediaManagerSDKError = await uploadResponse.json();
    const { error_description } = uploadRepsonseJson;
    return new Promise((resolve, reject) =>
      error_description ? reject(uploadRepsonseJson) : resolve(uploadRepsonseJson[0])
    );
  };
};

const getFolderId = (
  userId: string | undefined,
  siteOwnerId: string | undefined,
  visitorUploads?: VisitorUploads
) => {
  const isOwner = siteOwnerId === userId;
  const { folderId, shouldIncludeSiteOwner } = visitorUploads || {};
  const shouldUploadToFolder = shouldIncludeSiteOwner || !isOwner;
  return shouldUploadToFolder ? folderId : null;
};
