import {
  TIPTAP_CARD_HEADER_TYPE,
  TIPTAP_CARD_TYPE,
  TIPTAP_FIGURE_TYPE,
  TIPTAP_LAYOUT_TYPE,
} from './../../ricos-content/index.js';
import type { Resolver } from './../../ricos-types/index.js';
import { TOP_LEVEL_NODES } from './../top-level-nodes.js';
import { findParentNodeClosestToPos } from './../../tiptap/index.js';
import { NodeSelection } from './../../tiptap/pm/state.js';

export const canSetAsBanner: Resolver<boolean> = (_, __, editor) => {
  if (!editor?.state) {
    return false;
  }

  const selection = editor.state.selection;
  const selectedNode = selection instanceof NodeSelection ? selection.node : undefined;

  const parentFigure = findParentNodeClosestToPos(
    selection.$from,
    node => node.type.name === TIPTAP_FIGURE_TYPE
  );

  if (parentFigure) {
    const parentOfFigure = selection.$from.node(parentFigure.depth - 1);
    const isTopLevel = (TOP_LEVEL_NODES as readonly string[]).includes(parentOfFigure.type.name);
    if (!isTopLevel) {
      return false;
    }
  }

  // If the selected layout is a bottom banner, don't show the banner button
  if (
    selectedNode?.type.name === TIPTAP_LAYOUT_TYPE &&
    selectedNode.attrs?.banner?.position === 'BOTTOM'
  ) {
    return false;
  }
  const closestLayoutForExclusion = findParentNodeClosestToPos(
    selection.$from,
    node => node.type.name === TIPTAP_LAYOUT_TYPE
  );
  if (closestLayoutForExclusion?.node.attrs?.banner?.position === 'BOTTOM') {
    return false;
  }

  // Find the existing top banner in the relevant scope:
  // - inside a CARD: the layout in that card's CARD_HEADER child (if any);
  // - at doc root: a top-level layout with banner.position === 'TOP'.
  const parentCard = findParentNodeClosestToPos(
    selection.$from,
    node => node.type.name === TIPTAP_CARD_TYPE
  );

  let existingBannerId: string | undefined;
  if (parentCard) {
    parentCard.node.forEach(child => {
      if (child.type.name === TIPTAP_CARD_HEADER_TYPE && !existingBannerId) {
        existingBannerId = child.firstChild?.attrs.id;
      }
    });
  } else {
    const firstNode = editor.state.doc.content.firstChild;
    if (
      firstNode?.type.name === TIPTAP_LAYOUT_TYPE &&
      firstNode.attrs?.banner?.position === 'TOP'
    ) {
      existingBannerId = firstNode.attrs.id;
    }
  }

  if (!existingBannerId) {
    return true;
  }

  // A banner already exists in scope — show the toggle only on the banner itself.
  if (selectedNode?.type.name === TIPTAP_LAYOUT_TYPE) {
    return selectedNode.attrs?.id === existingBannerId;
  }

  const closestLayout = findParentNodeClosestToPos(
    selection.$from,
    node => node.type.name === TIPTAP_LAYOUT_TYPE
  );

  if (closestLayout) {
    return closestLayout.node.attrs?.id === existingBannerId;
  }

  return false;
};
