import { ToggleButton } from '@wix/design-system';
import type { IconComponent } from '@wix/wix-ui-icons-common/core';
import classNames from 'classnames';
import React, { useContext, useMemo } from 'react';

import { RicosContext, ZIndexContext } from './../../ricos-context/index.js';
import { RICOS_INERT_TOOLTIP_HOST } from './../ricos-inert-tooltip-host.js';
import { dataHook } from './../../wix-rich-content-common/index.js';

import classes from './toolbar-button-scss.js';

// Module scope: the component destructures a `dataHook` prop, which shadows the helper inside it.
const INERT_TOOLTIP_HOST_SELECTOR = dataHook(RICOS_INERT_TOOLTIP_HOST);

// WDS places either a visible label or a tooltip, never both — a `labelValue` disables the
// tooltip. Encoded so a caller can't pass both and silently lose the tooltip; a label whose
// accessible name should read differently passes `ariaLabel`.
type LabelOrTooltip =
  | { label?: React.ReactNode; tooltip?: never }
  | { label?: never; tooltip?: string };

type Props = {
  active?: boolean;
  disabled?: boolean;
  onClick?: (e: React.PointerEvent<HTMLButtonElement>) => void;
  dataHook?: string;
  className?: string;
  // Both slots render into one icon box and may hold more than one glyph (icon + chevron, for
  // dropdown triggers). Alongside `label` they render as an adjacent pair beside it — the
  // label cannot sit between prefix and suffix (a WDS constraint).
  prefix?: IconComponent;
  suffix?: IconComponent;
  ariaLabel?: string;
} & LabelOrTooltip &
  Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'prefix'>;

type NativeButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  buttonRef: React.Ref<HTMLButtonElement>;
  ricos: { dataHook: string; ariaLabel?: string; disabled: boolean };
  // ButtonCore always passes its own hook down; we only fall back to it.
  'data-hook'?: string;
};

// ToggleButton spreads unrecognised props onto whatever `as` receives, so rendering the
// <button> ourselves keeps four things ToggleButton would otherwise own:
//
// - the ref. ToggleButton is a class component, but callers need the DOM node for popover
//   positioning (floating-ui reference element) and imperative focus.
// - `data-hook`. ToggleButton puts its own on the button and ours on the wrapping Tooltip;
//   testkits and e2e select the real button.
// - the native `disabled` attribute. ButtonCore only sets `aria-disabled`.
// - `aria-label`. ToggleButton stamps `labelValue.toString()` after the rest-prop spread, so
//   a ReactNode label reads as "[object Object]" and a caller's `ariaLabel` is lost.
//
// Module scope: an inline component is a new type every render, which would remount the button.
const NativeButton = ({ buttonRef, ricos, ...props }: NativeButtonProps) => (
  <button
    {...props}
    ref={buttonRef}
    // Fall back to ToggleButton's own hook when we have nothing to write.
    data-hook={ricos.dataHook || props['data-hook']}
    aria-label={ricos.ariaLabel}
    disabled={ricos.disabled}
  />
);

export const ToolbarButton = React.forwardRef<HTMLButtonElement, Props>(
  (
    {
      active,
      disabled,
      tooltip,
      onClick,
      dataHook,
      className,
      label,
      prefix: Prefix,
      suffix: Suffix,
      ariaLabel,
      ...props
    }: Props,
    ref
  ) => {
    const { isMobile, portal } = useContext(RicosContext);
    // The tooltip layer, like every other tooltip in the repo. Demoting it below the modal layer
    // would also stop it swallowing dropdown clicks, but would hide it behind any open panel.
    const zIndex = useContext(ZIndexContext)?.getZIndex('TOOLTIP');
    // The single host `RicosPortal` renders. Read from the DOM rather than threaded through
    // context: it is the same node every render, so `appendTo` stays reference-equal and WDS
    // never re-appends the popover. Absent outside an editor — viewer, stories, specs.
    const tooltipHost = useMemo(
      () => portal?.querySelector<HTMLElement>(INERT_TOOLTIP_HOST_SELECTOR) ?? undefined,
      [portal]
    );

    return (
      <ToggleButton
        as={NativeButton}
        buttonRef={ref}
        ricos={{
          dataHook: classNames(dataHook, { disabled, active }),
          // No value removes the attribute, so the name falls back to the visible label.
          ariaLabel: ariaLabel ?? tooltip,
          disabled: !!disabled,
        }}
        selected={active}
        disabled={disabled}
        size={isMobile ? 'medium' : 'small'}
        labelPlacement={label ? (Suffix ? 'start' : 'end') : tooltip ? 'tooltip' : undefined}
        labelValue={label ?? tooltip}
        className={classNames(className, { [classes.mobileToolbarButton]: isMobile })}
        onClick={disabled ? undefined : onClick}
        // Annotated because `as` selects ToggleButton's open-ended prop branch, typed `any`.
        onMouseDown={(e: React.MouseEvent<HTMLButtonElement>) => e.preventDefault()}
        // `placement` is spelled out because ToggleButton's `defaultProps.tooltipProps` is
        // replaced by any object passed here, not merged into; `flip: false` then keeps the
        // bubble above the button instead of letting popper drop it over the panel the button
        // opens. No `className`: WDS spreads `tooltipProps` over its own, dropping its layout.
        // `fixed` is not fixed positioning — it turns off popper's `preventOverflow`, whose
        // boundary `appendTo` would otherwise make this zero-size host div. Both it and
        // `zIndex` only ship with the host, since neither means anything without it.
        tooltipProps={
          tooltip
            ? {
                moveBy: { y: 8 },
                placement: 'top',
                flip: false,
                ...(tooltipHost ? { appendTo: tooltipHost, fixed: true, zIndex } : {}),
              }
            : undefined
        }
        // Otherwise a button with neither label nor tooltip shows an empty bubble on hover.
        tooltipDisabled={!tooltip}
        skin="inverted"
        {...props}
      >
        {/* WDS clones this "icon" child to inject its own flex-shrink-blocking class + size
            (see ToggleButton.js), but only components that forward those props onto their root
            element receive it — ricos' `prefix`/`suffix` render props don't. Wrapping in a plain
            `<span>` (which does accept the cloned props) gives WDS something real to protect, so
            the icon can't get flex-shrunk to invisibility in a cramped toolbar when a label is
            also present. The span renders even with both slots empty because ToggleButton
            cloneElement's its child unconditionally and crashes on a missing one;
            `.content:empty` hides it from layout. */}
        <span
          className={classNames(classes.content, {
            [classes.noLabel]: !label,
          })}
        >
          {Prefix && <Prefix />}
          {Suffix && <Suffix />}
        </span>
      </ToggleButton>
    );
  }
);
