import type { WixClient } from '@wix/sdk/client';
import React from 'react';

import { useDevConnectionState } from './../../ricos-context/index.js';
import {
  type GetWixClientPromise,
  useGetWixClientPromise,
} from './../request-service-provider/use-get-wix-client-promise.js';
import { wrapWithNetworkConditions } from './../../wix-rich-content-common/devTools/wrap-with-network-conditions.js';

const RequestServiceContext = React.createContext<RequestService>(
  null as unknown as RequestService
);

export type RequestService = {
  makeRequest(input: string | URL, init?: RequestInit): Promise<Response>;
  getWixClientPromise: GetWixClientPromise;
};

export const RequestServiceProvider: React.FC<
  React.PropsWithChildren<{
    wixClient?: WixClient;
    instance?: string;
  }>
> = ({ children, wixClient: existingWixClient, instance }) => {
  const connectionState = useDevConnectionState();
  const { getWixClientPromise } = useGetWixClientPromise(instance ?? '', existingWixClient);

  React.useEffect(() => {
    if (!existingWixClient && !instance) {
      console.warn(
        'Ricos: neither wixClient nor instance was provided. Requests will not be authenticated.'
      );
    }
  }, [existingWixClient, instance]);

  const service = React.useMemo<RequestService>(() => {
    return {
      getWixClientPromise,
      makeRequest: wrapWithNetworkConditions(
        async (relativeUrl: string | URL, options: RequestInit) => {
          const wixClient = await getWixClientPromise();
          return wixClient.fetchWithAuth(relativeUrl, options);
        },
        () => connectionState
      ),
    };
  }, [getWixClientPromise, connectionState]);

  return (
    <RequestServiceContext.Provider value={service}>{children}</RequestServiceContext.Provider>
  );
};

export const useRequestService = () => {
  const context = React.useContext(RequestServiceContext);

  if (!context) {
    throw new Error('useRequestService must be used within a RequestServiceProvider');
  }

  return context;
};
