import { ListItemSelect as WdsListItemSelect } from '@wix/design-system';
import classNames from 'classnames';
import React, { useContext, useLayoutEffect, useRef } from 'react';

import { RicosContext } from './../../ricos-context/index.js';

import { LIST_ITEM_SELECT, LIST_ITEM_SELECT_CONTENT } from './data-hooks.js';
import classes from './list-item-select-scss.js';

type Props = {
  dataHook?: string;
  prefix?: React.ReactNode;
  // Required because WDS renders the title unconditionally: a titleless row would still emit
  // the title element and the vertical margin WDS puts on its wrapper.
  title: React.ReactNode;
  /**
   * Trailing content, e.g. a toggle switch or an info icon. WDS wraps it in a `Text`,
   * so anything interactive placed here needs `list-item-select.scss`'s suffix rules
   * to sit upright in the row and to stay clickable while the row is disabled.
   */
  suffix?: React.ReactNode;
  selected?: boolean;
  disabled?: boolean;
  onSelect?: (
    event: React.PointerEvent<HTMLDivElement> | React.KeyboardEvent<HTMLDivElement>
  ) => void;
  className?: string;
  // `onClick`/`onKeyDown` are forbidden rather than merged: rest props are spread last, so a
  // consumer handler would replace the disabled guard and the `stopPropagation` below.
} & Omit<
  React.HTMLAttributes<HTMLDivElement>,
  'onSelect' | 'prefix' | 'title' | 'onClick' | 'onKeyDown'
>;

// WDS stamps these on its own root too. That root has no role, so they are inert there, but each
// is a second match for the attribute queries the testkits use — which broke text-align's.
// Stripping is the only lever: WDS offers no prop to suppress them, so the fix is upstream.
const WDS_DUPLICATED_ATTRIBUTES = ['aria-selected', 'aria-disabled', 'data-selected'];

/**
 * Row of a ricos dropdown. The interior is WDS `ListItemSelect`; the wrapper exists because WDS
 * accepts no rest props — the option role, tab order, keyboard selection and the event
 * containment nested dropdowns rely on all need an element we own.
 *
 * No `subtitle` or row tooltip: nothing has ever passed one, and each needs its own WDS
 * workaround to render. Add them back when a row actually needs them.
 */
export const ListItemSelect: React.FC<Props> = ({
  title,
  prefix,
  suffix,
  dataHook,
  selected = false,
  disabled = false,
  onSelect,
  className,
  ...props
}) => {
  const { isMobile } = useContext(RicosContext);
  const rowRef = useRef<HTMLDivElement>(null);

  // No dep array: a dep list would have to predict both when WDS re-stamps the attributes and
  // every reason its root node is replaced. Three `removeAttribute` calls per commit are cheap.
  useLayoutEffect(() => {
    const wdsRow = rowRef.current?.firstElementChild;
    if (!wdsRow) {
      return;
    }

    WDS_DUPLICATED_ATTRIBUTES.forEach(attribute => wdsRow.removeAttribute(attribute));
  });

  return (
    <div
      ref={rowRef}
      className={classNames(classes.root, className)}
      data-hook={classNames(LIST_ITEM_SELECT, dataHook)}
      role="option"
      aria-selected={selected}
      aria-disabled={disabled}
      tabIndex={disabled ? -1 : 0}
      onClick={(e: React.PointerEvent<HTMLDivElement>) => {
        if (disabled) {
          return;
        }

        e.stopPropagation();
        onSelect?.(e);
      }}
      onKeyDown={e => {
        if (disabled) {
          return;
        }

        if (e.key === 'Enter' || e.key === ' ') {
          e.stopPropagation();
          e.preventDefault();
          onSelect?.(e);
        }
      }}
      {...props}
    >
      <WdsListItemSelect
        // Overridden so WDS does not restamp the wrapper's own hook on a nested element,
        // which would make every driver query match twice.
        dataHook={LIST_ITEM_SELECT_CONTENT}
        className={classes.content}
        size={isMobile ? 'medium' : 'small'}
        prefix={prefix}
        suffix={suffix}
        title={title}
        selected={selected}
        disabled={disabled}
      />
    </div>
  );
};
