import { getTextDirection } from './../../ricos-content/get-text-direction.js';
import { TextSelection } from './../../tiptap/pm/state.js';
import type { EditorView } from './../../tiptap/pm/view.js';
import { findNodeById } from './../../tiptap-editor/helpers/index.js';

/**
 * Activates a figure caption by making it visible and focusing on it.
 * @param view - The TipTap editor view instance
 * @param captionId - The ID of the caption node to activate
 * @returns boolean indicating success (true) or failure (false)
 */
export const activateCaption = (view: EditorView, captionId: string): boolean => {
  const captionNodePos = findNodeById(view.state.tr, captionId)[0];

  if (!captionNodePos) {
    return false;
  }

  const { tr } = view.state;
  tr.setNodeAttribute(captionNodePos.pos, 'showEmpty', true);
  view.dispatch(tr);

  // Needs to be done in next tick due to Safari handling of focus.
  setTimeout(() => {
    const captionNode = captionNodePos.node;
    const hasContent = captionNode.content.size > 0;
    let selectionPos = captionNodePos.pos + 1;

    if (hasContent) {
      const captionText = captionNode.textContent;
      const direction = getTextDirection(captionText);
      selectionPos = direction === 'rtl' ? selectionPos : selectionPos + captionNode.content.size;
    }

    const { tr } = view.state;
    tr.setSelection(TextSelection.create(tr.doc, selectionPos, selectionPos));
    view.dispatch(tr);
    view.focus();
  }, 0);

  return true;
};
