import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';

import { DropdownModal } from '../../dropdown-modal/dropdown-modal.js';
import { ListItemSelect } from '../../list-item-select/list-item-select.js';

type NodeSizeDropdownProps = {
  dropdownOptions: {
    id: string;
    dataHook: string;
    label: string;
    icon: React.ComponentType;
    iconMobile: React.ComponentType;
  }[];
  onSelect: (value: string) => void;
  selectedId?: string;
  closeModal: () => void;
};

export const NodeSizeDropdown: React.FC<NodeSizeDropdownProps> = ({
  dropdownOptions,
  onSelect,
  selectedId,
  closeModal,
}) => {
  const { t, isMobile } = useContext(RicosContext);

  return (
    <DropdownModal
      onCloseButtonClick={closeModal}
      title={t('ButtonModal_Size_Section')}
      options={dropdownOptions.map(
        ({ iconMobile: IconMobile, icon: Icon, label: text, id: commandKey, dataHook }) => (
          <ListItemSelect
            key={commandKey}
            dataHook={dataHook}
            prefix={isMobile && IconMobile ? <IconMobile /> : Icon ? <Icon /> : null}
            title={text}
            selected={commandKey === selectedId}
            onSelect={() => {
              onSelect(commandKey);
              closeModal();
            }}
          />
        )
      )}
    />
  );
};
