import type { ImageData_Crop } from './../../ricos-schema/next-schema/index.js';

const EPSILON = 0.0001;

const clamp = (value: number, min: number, max: number): number =>
  Math.min(Math.max(value, min), max);

type PixelCropArgs = {
  crop?: ImageData_Crop | null;
  sourceWidth: number | undefined;
  sourceHeight: number | undefined;
};

export const normalize = (crop?: ImageData_Crop | null): Required<ImageData_Crop> => ({
  x: crop?.x ?? 0,
  y: crop?.y ?? 0,
  width: crop?.width && crop.width > 0 ? crop.width : 1,
  height: crop?.height && crop.height > 0 ? crop.height : 1,
});

export const isCropped = (crop?: ImageData_Crop | null): crop is ImageData_Crop => {
  if (!crop) {
    return false;
  }

  const { width = 1, height = 1 } = crop;
  if (width <= 0 || height <= 0) {
    return false;
  }

  const normalized = normalize(crop);
  return (
    normalized.x > EPSILON ||
    normalized.y > EPSILON ||
    normalized.width < 1 - EPSILON ||
    normalized.height < 1 - EPSILON
  );
};

export const toCropAttribute = (crop?: ImageData_Crop | null): ImageData_Crop | null =>
  isCropped(crop) ? crop : null;

export const toPixelCrop = ({ crop, sourceWidth, sourceHeight }: PixelCropArgs) => {
  if (!isCropped(crop) || !sourceWidth || !sourceHeight) {
    return;
  }

  const normalized = normalize(crop);
  const x = clamp(Math.round(normalized.x * sourceWidth), 0, sourceWidth - 1);
  const y = clamp(Math.round(normalized.y * sourceHeight), 0, sourceHeight - 1);

  return {
    x,
    y,
    width: clamp(Math.round(normalized.width * sourceWidth), 1, sourceWidth - x),
    height: clamp(Math.round(normalized.height * sourceHeight), 1, sourceHeight - y),
  };
};
