import { getPlaceholder as getImageKitPlaceholder } from '@wix/image-kit';

import type { ImageProps } from './../../bundled-dependencies/wix-image.js';
import type { UserDomainMediaConfig } from './../../ricos-types/index.js';

import { applyUserDomainMedia } from './apply-user-domain-media.js';
import { WIX_MEDIA_BASE_URL } from './media-url-consts.js';

const WIX_MEDIA_IMAGE_PREFIX = `${WIX_MEDIA_BASE_URL}media/`;
const SCHEME_RE = /^[a-z]+:/;

type GetPlaceholder = NonNullable<ImageProps['getPlaceholder']>;

/**
 * Builds the `getPlaceholder` prop for `@wix/image`, whose built-in placeholder resolves against a
 * hardcoded wixstatic base and so keeps site-owned images off the site's domain even when the
 * rendered image already honours it. Returns `undefined` when the host did not configure
 * `userDomainMedia`, leaving `@wix/image` on its own implementation.
 */
export const createUserDomainPlaceholder = (
  userDomainMedia?: UserDomainMediaConfig
): GetPlaceholder | undefined => {
  const { baseUrl, prefixes = [] } = userDomainMedia ?? {};
  if (!baseUrl || prefixes.length === 0) {
    return undefined;
  }

  // image-kit returns a path relative to the media base, except when the source uri is already
  // absolute, in which case it hands the URL back untouched.
  const toAbsolute = (value: string) =>
    SCHEME_RE.test(value) ? value : `${WIX_MEDIA_IMAGE_PREFIX}${value}`;

  return ({ fittingType, src, target, options }) => {
    const placeholder = getImageKitPlaceholder(fittingType, src, target, {
      ...options,
      autoEncode: true,
    });

    if (placeholder?.uri) {
      placeholder.uri = applyUserDomainMedia(toAbsolute(placeholder.uri), userDomainMedia);
    }

    if (placeholder?.srcset?.dpr) {
      placeholder.srcset.dpr = placeholder.srcset.dpr.map(entry =>
        applyUserDomainMedia(toAbsolute(entry), userDomainMedia)
      );
    }

    // Same shape `@wix/image` builds internally from this call; its prop type is just stricter
    // about optional members than image-kit's return type.
    return placeholder as ReturnType<GetPlaceholder>;
  };
};
