import {
  TIPTAP_CARD_CONTENT_TYPE,
  TIPTAP_CARD_FOOTER_TYPE,
  TIPTAP_CARD_HEADER_TYPE,
} from './../ricos-content/index.js';
import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';

// Wrapper nodes that sit between the doc root and the actual content blocks.
// Used in two ways:
//   - Pattern A: check `$pos.parent.type.name` to test whether a block sits at a
//     top-level position (paragraph in CARD_CONTENT, layout in CARD_FOOTER, etc.).
//   - Pattern B: walk `firstChild` / `lastChild` through wrappers to reach the
//     first/last actual content block.
export const TOP_LEVEL_NODES = [
  'doc',
  Node_Type.CARD,
  TIPTAP_CARD_HEADER_TYPE,
  TIPTAP_CARD_CONTENT_TYPE,
  TIPTAP_CARD_FOOTER_TYPE,
] as const;
